  "atomic_questions": [
    "Is there a limit on how many units can be purchased in any single month (a monthly purchase budget or cap), or can you buy any non-negative quantity at that month's buy price?"
  ],
  "rationale": "The response asks for a single policy choice regarding monthly purchase limits, which constitutes one semantically independent question."
}

